SELECT (SELECT COUNT(*) FROM raw WHERE e<s) negative_intervals,(SELECT COUNT(*) FROM raw WHERE e=s) zero_intervals,(SELECT COUNT(*) FROM firsts f LEFT JOIN wtt.edit e ON e.rev_id=f.born_rev WHERE e.rev_id IS NULL) missing_born_edits,(SELECT COUNT(*) FROM firsts f JOIN wtt.edit e ON e.rev_id=f.born_rev WHERE e.saved_at<>f.first_at OR e.page_id<>f.page_id) mismatched_births,(SELECT COUNT(*) FROM pairs WHERE delay_seconds<0) negative_delays;
